lifecycle.secure:
app.get('/invoice/:id', requireLogin, async (req, res) => {
  const inv = await db.getInvoice(req.params.id);
  // authorize the OBJECT against the caller's identity
  if (!inv || inv.ownerId !== req.user.id) return res.sendStatus(404);
  res.json(inv);
});
